#pragma once

// KS1 equivalence ≡ (HSW 2021, §II eq (2)) — Track 2 phase K1.
//
// KS1 reuses core::FormulaHandle in NNF (the LKR convention): a literal is a
// PredicateInstance or Compound{Not, atom}; ⊥ is Compound{Bottom}; the truth
// unit ⊤ ("1") is encoded as ¬⊥ = Compound{Not, Bottom}. There is no parallel
// KS1 formula type.
//
// `≡` is the congruence generated by (on rectified formulas):
//
//     A ∧ B ≡ B ∧ A            (A ∧ B) ∧ C ≡ A ∧ (B ∧ C)
//     A ∨ B ≡ B ∨ A            (A ∨ B) ∨ C ≡ A ∨ (B ∨ C)
//     ∀x.∀y.A ≡ ∀y.∀x.A        ∀x.(A ∧ B) ≡ (∀x.A) ∧ B    (x not free in B)
//     ∃x.∃y.A ≡ ∃y.∃x.A        ∃x.(A ∧ B) ≡ (∃x.A) ∧ B    (x not free in B)
//
// We decide ≡ by canonicalization: `canonicalize` rewrites a formula to a
// unique representative of its ≡-class, and `equiv(a,b)` is handle-equality of
// the two canonical forms (equal canonical structures intern to the same
// FormulaHandle in the shared registry).
//
// NOTE — this is NOT raw fograph equality. Thm 8 says A≡B ⟺ [[A]]=[[B]], but
// our comb::Fograph is not a canonical representative under vertex reordering
// (commutativity permutes vertices) and has no operator==. See
// translate/KS1_TRACK2_DESIGN.md §2 "K1 finding".
//
// SCOPE (K1, this increment): the PROPOSITIONAL fragment of ≡ is implemented —
// associativity + commutativity of ∧/∨ (the first two rows above), plus
// recursive canonicalization under quantifiers (so e.g. ∀x.(A∧B) ≡ ∀x.(B∧A)).
// The quantifier-shift equations (binder swap ∀x.∀y≡∀y.∀x / ∃x.∃y≡∃y.∃x and
// mini-scoping ∀x.(A∧B)≡(∀x.A)∧B / ∃x.(A∧B)≡(∃x.A)∧B) are NOT yet handled —
// `equiv` is therefore SOUND but INCOMPLETE on quantifier shifts (it never
// reports a false ≡; it may miss a true one). Completing them is the next K1
// increment. Nothing consumes `equiv` yet, so the incompleteness is contained.

#include "src/core/formula.h"

namespace logic::proof::ks1 {

// Canonical representative of h's ≡-class (propositional fragment; see scope
// note above). Idempotent: canonicalize(canonicalize(h)) == canonicalize(h).
// Allocates rebuilt ∧/∨ nodes through `fb`'s shared registry.
FormulaHandle canonicalize(FormulaBuilder& fb, FormulaHandle h);

// True iff a ≡ b. Decided as canonicalize(a) == canonicalize(b). `a` and `b`
// must be built in the same GlobalContext as `fb`.
bool equiv(FormulaBuilder& fb, FormulaHandle a, FormulaHandle b);

}  // namespace logic::proof::ks1
